// Limit size to keep fuzzer fast.
std::string src = FUZZ_PARAM_STR();
if (src.size() > 2048) src.resize(2048);
ds->data = src;
ds->pos = 0;
ds->seekable = (int)(*FUZZ_PARAM(unsigned int) & 1u);
// fread-like: writes into ptr from datasource; returns count of items read.
auto read_fp = +[](void *ptr, size_t size, size_t nmemb, void *datasource) -> size_t {
  if (size == 0 || nmemb == 0) return 0;
  DS *s = (DS*)datasource;
  size_t want = size * nmemb;
  size_t avail = (s->pos < s->data.size()) ? (s->data.size() - s->pos) : 0;
  size_t rbytes = want < avail ? want : avail;
  if (rbytes) { memcpy(ptr, s->data.data() + s->pos, rbytes); s->pos += rbytes; }
  return rbytes / size; // items read
};
// fseek-like; must return -1 if unseekable.
auto seek_fp = +[](void *datasource, ogg_int64_t offset, int whence) -> int {
  DS *s = (DS*)datasource;
  if (!s->seekable) return -1;
  ogg_int64_t base = 0;
  if (whence == SEEK_SET) base = 0;
  else if (whence == SEEK_CUR) base = (ogg_int64_t)s->pos;
  else if (whence == SEEK_END) base = (ogg_int64_t)s->data.size();
  else return -1;
  ogg_int64_t np = base + offset;
  if (np < 0 || (uint64_t)np > s->data.size()) return -1;
  s->pos = (size_t)np;
  return 0;
};
// fclose-like: free datasource.
auto close_fp = +[](void *datasource) -> int { delete (DS*)datasource; return 0; };
// ftell-like: return current position.
auto tell_fp = +[](void *datasource) -> long { DS *s = (DS*)datasource; return (long)s->pos; };
ov_callbacks cbs; cbs.read_func = read_fp; cbs.seek_func = seek_fp; cbs.close_func = close_fp; cbs.tell_func = tell_fp;
